        FRebuildActivityCategoryViewModel Category;Category.Cycle=Cycle.Key;Category.Title=FText::FromString(Cycle.Value);const auto List=J::ActivitiesForCycle(View,Cycle.Key);Category.bActivitiesProvided=List.bProvided;Category.bHasCount=List.bProvided;Category.Count=List.Items.Num();Category.State=ActivityState(W,List.bProvided,List.Items.IsEmpty());
