        J::FRequest Request;Request.Action=J::EAction::StartLaunch;Request.bConfirmed=true;const auto Gate=J::Evaluate(Context,Request);Vm.bCanStart=Gate.bAllowed;Vm.StartDisabledReason=FText::FromString(Gate.Reason);Vm.bCanEnterWorld=View.Launch.IsValid();Vm.StartTimeText=D::DateText(View.Launch,TEXT("start"));Vm.EndTimeText=D::DateText(View.Launch,TEXT("end"));const auto Personal=D::Object(View.Launch,TEXT("personal"));Vm.PersonalScoreText=D::NumericText(Personal,TEXT("score"));Vm.bHasPersonalScore=!Vm.PersonalScoreText.IsEmpty();Vm.CompleteRoundsText=D::NumericText(Personal,TEXT("complete_count"));Vm.bHasCompleteRounds=!Vm.CompleteRoundsText.IsEmpty();
