    {FRebuildLaunchRankViewModel Vm;Vm.ContentKey=SemanticKey;Vm.EventId=FName(*D::String(View.Launch,TEXT("id")));Vm.StatusText=Status;Vm.State=ActivityState(W,View.Launch.IsValid());const FString Self=D::String(D::Object(DisplaySnapshot,TEXT("identity")),TEXT("user"));for(const auto& Row:D::Rows(View.Launch,TEXT("leaderboard"),&Vm.bRowsProvided)){FRebuildLaunchRankRowViewModel Entry;Entry.ParticipantId=FName(*D::String(Row,TEXT("user")));Entry.RankText=D::NumericText(Row,TEXT("rank"));Entry.bRankKnown=!Entry.RankText.IsEmpty();Entry.DisplayName=D::Text(Row,TEXT("name"));Entry.bNameKnown=!Entry.DisplayName.IsEmpty();Entry.ContributionText=D::NumericText(Row,TEXT("score"));Entry.bContributionKnown=!Entry.ContributionText.IsEmpty();Entry.bIsCurrentParticipant=!Self.IsEmpty()&&Entry.ParticipantId==FName(*Self);if(Entry.bIsCurrentParticipant){Vm.OwnRankText=Entry.RankText;Vm.bOwnRankKnown=Entry.bRankKnown;Vm.OwnContributionText=Entry.ContributionText;Vm.bOwnContributionKnown=Entry.bContributionKnown;}Vm.Rows.Add(Entry);}Rank->ApplyViewModel(Vm);}
    if(auto* Offline=Cast<URebuildOfflineRewardsWidget>(OwnerPage))
    {FRebuildOfflineRewardsViewModel Vm;Vm.ContentKey=SemanticKey;Vm.StatusText=Status;const auto Data=D::Object(DisplaySnapshot,TEXT("offline_reward"));Vm.State=ActivityState(W,Data.IsValid());Vm.bConnected=Context.bConnected;Vm.bBusy=Context.bBusy;Vm.OfflineTotalQiText=D::NumericText(Data,TEXT("total_qi"));Vm.bTotalQiKnown=!Vm.OfflineTotalQiText.IsEmpty();Vm.AcknowledgedQiText=D::NumericText(Data,TEXT("acknowledged_qi"));Vm.bAcknowledgedQiKnown=!Vm.AcknowledgedQiText.IsEmpty();Vm.bCanAcknowledge=CanDispatch()&&Data.IsValid();for(const auto& Row:D::Rows(DisplaySnapshot,TEXT("records"),&Vm.bReceiptsProvided)){const auto Reward=D::Object(Row,TEXT("offline_reward"));if(!Reward)continue;FRebuildOfflineReceiptRowViewModel Receipt;Receipt.ReceiptId=FName(*D::String(Row,TEXT("id")));Receipt.SourceText=D::Text(Row,TEXT("name"));Receipt.bSourceKnown=!Receipt.SourceText.IsEmpty();Receipt.TimeText=D::DateText(Row,TEXT("created"));Receipt.bTimeKnown=!Receipt.TimeText.IsEmpty();Receipt.QiText=D::NumericText(Reward,TEXT("total_qi"));Receipt.bQiKnown=!Receipt.QiText.IsEmpty();Vm.Receipts.Add(Receipt);}Offline->ApplyViewModel(Vm);}
