    {FRebuildConsignmentViewModel Vm;Vm.ContentKey=SemanticKey;Vm.StatusText=Status;Vm.bConnected=Connected;Vm.bBusy=Busy;Vm.bQueryAllowed=CanDispatch();Vm.Offset=QueryOffset;Vm.bOwnedOnly=bOwnedOnly;Vm.SelectedListingId=FName(*SelectedEntry);Vm.SelectedInventoryItemId=FName(*SecondaryEntry);Vm.DraftQuantityText=DraftQuantity;Vm.DraftUnitPriceText=DraftPrice;const auto Catalog=D::Catalog(DisplaySnapshot,TEXT("market"),QueryOffset),MarketState=D::Object(DisplaySnapshot,TEXT("market"));const auto Rows=Catalog?D::Rows(Catalog,TEXT("rows"),&Vm.bListingsProvided):D::Rows(MarketState,TEXT("listings"),&Vm.bListingsProvided);Vm.State=ActivityState(W,Vm.bListingsProvided,Rows.IsEmpty());Vm.PageSize=Rows.Num();int32 Total=0;Vm.bHasNextPage=D::Integer(Catalog,TEXT("total"),Total)&&QueryOffset+Rows.Num()<Total;for(const auto& Row:Rows){FRebuildConsignmentListingViewModel Entry;Entry.ListingId=FName(*D::String(Row,TEXT("id")));Entry.ListingVersion=FName(*D::Version(Row));Entry.ItemId=FName(*D::String(Row,TEXT("item_id")));Entry.Name=D::Text(Row,TEXT("name"));if(Entry.Name.IsEmpty())Entry.Name=D::Text(D::FindCatalog(DisplaySnapshot,TEXT("items"),Entry.ItemId.ToString()),TEXT("name"));Entry.bNameKnown=!Entry.Name.IsEmpty();Entry.PriceText=D::NumericText(Row,TEXT("unit_price"));Entry.bPriceKnown=!Entry.PriceText.IsEmpty();Entry.StateText=D::Text(Row,TEXT("status"));bool Own=D::Boolean(Row,TEXT("is_own"));for(const auto& OwnRow:D::Rows(MarketState,TEXT("own_listings")))Own|=D::String(OwnRow,TEXT("id"))==Entry.ListingId.ToString();const bool OwnershipKnown=D::Has(Row,TEXT("is_own"))||D::Has(MarketState,TEXT("own_listings"));Entry.bCanBuy=CanDispatch()&&OwnershipKnown&&!Own&&!Entry.ListingId.IsNone()&&!Entry.ListingVersion.IsNone();Vm.Listings.Add(Entry);}
        const auto Items=D::Catalog(DisplaySnapshot,TEXT("items"));for(const auto& Row:D::Rows(Items,TEXT("rows"),&Vm.bInventoryProvided)){FRebuildConsignmentInventoryEntryViewModel Entry;Entry.ItemId=FName(*D::String(Row,TEXT("item_id")));Entry.Name=D::Text(Row,TEXT("name"));Entry.bNameKnown=!Entry.Name.IsEmpty();Entry.AvailableCountText=D::NumericText(Row,TEXT("owned_count"));Entry.bCountKnown=!Entry.AvailableCountText.IsEmpty();Entry.bCanList=CanDispatch()&&D::Boolean(Row,TEXT("tradeable"));Vm.InventoryEntries.Add(Entry);}Vm.bPriceValidationAvailable=CanDispatch();Vm.bCreateAllowed=CanDispatch()&&Vm.bInventoryProvided;Market->ApplyViewModel(Vm);}
