void UInkRebuildFeatureHost::HandleActivity(FRebuildActivityActionRequest Request)
{
    if(!IsActivePage())return;const FString Action=Request.Action.ToString();
    if(Action==TEXT("back")){HandleBack();return;}
    if(Action==TEXT("open-launch")){Navigate(TEXT("LaunchEvent"));return;}if(Action==TEXT("open-launch-rank")){Navigate(TEXT("LaunchRank"));return;}if(Action==TEXT("open-world")){Navigate(TEXT("WorldCultivation"));return;}
    if(Action==TEXT("activity-cycle")){Navigate(Request.Cycle==TEXT("limited")?TEXT("TimedActivities"):Request.Cycle==TEXT("daily")?TEXT("DailyActivities"):TEXT("Activities"));return;}
    if(Action==TEXT("open-activity-detail")){Navigate(Request.Cycle==TEXT("limited")?TEXT("TimedActivityDetail"):TEXT("DailyActivityDetail"),Request.EntryId.ToString());return;}
    if(Action==TEXT("sign-in")){HandleSignIn(Request.ExpectedServiceDay);return;}
    if(Action==TEXT("start-launch"))
    {if(!Request.bConfirmed)return;const auto State=Service()?Service()->Snapshot():nullptr;const auto Identity=D::Object(State,TEXT("identity")),Guild=D::Object(State,TEXT("guild")),Manifest=D::Object(State,TEXT("manifest"));const auto& Captured=Request.StartSubject;if(Captured.AnchorUserId!=D::String(Identity,TEXT("user"))||Captured.GuildId!=D::String(Guild,TEXT("id"))||Captured.ProfileId!=D::String(Manifest,TEXT("profile"))||Captured.RulesVersion!=D::String(Manifest,TEXT("rule_version")))return;J::FRequest R;R.Action=J::EAction::StartLaunch;R.bConfirmed=true;FString Message;J::Submit(Service(),IsActivePage(),R,Message);Feedback(Message);RefreshAuthority(true);return;}
    if(Action==TEXT("ack-offline")){if(D::Object(Service()?Service()->Snapshot():nullptr,TEXT("offline_reward")))Submit(TEXT("AcknowledgeOfflineReward"),MakeShared<FJsonObject>());RefreshAuthority(true);return;}
    if(Action==TEXT("query-shop")||Action==TEXT("query-market")){QueryCatalog(Action==TEXT("query-shop")?TEXT("shop"):TEXT("market"),Request.Offset,Request.bOwnedOnly);return;}
    if(Action==TEXT("ui.market.draft")){DraftQuantity=Request.QuantityText;DraftPrice=Request.PriceText;return;}
    if(Request.Action.IsNone()){if(Request.Cycle==TEXT("inventory"))SecondaryEntry=Request.EntryId.ToString();else SelectedEntry=Request.EntryId.ToString();SemanticKey.Empty();return;}
    if(Action==TEXT("start-supported-activity")||Action==TEXT("end-supported-activity"))
    {
        const FString Id=Request.EntryId.ToString();if(Id!=SelectedEntry||(Id!=TEXT("ACT_SHARED")&&Id!=TEXT("WEEK_GUARD")&&Id!=TEXT("WEEK_IRON"))||(Action==TEXT("end-supported-activity")&&Id!=TEXT("ACT_SHARED")))return;
        bool Enabled=false;const auto State=Service()?Service()->Snapshot():nullptr;for(const auto& Row:J::Read(J::Capture(Service(),IsActivePage())).Templates.Items)if(D::String(Row,TEXT("activity_id"))==Id)Enabled=D::Boolean(Row,TEXT("enabled"));if(!Enabled)return;
        auto Args=MakeShared<FJsonObject>();if(Action==TEXT("start-supported-activity"))Args->SetStringField(TEXT("activity_id"),Id);Submit(Action==TEXT("start-supported-activity")?TEXT("StartActivity"):TEXT("EndActivity"),Args);RefreshAuthority(true);return;
    }
    if(!Request.bConfirmed)return;const auto State=Service()?Service()->Snapshot():nullptr;
    if(Action==TEXT("purchase"))
    {const auto Row=D::FindCatalog(State,TEXT("shop"),Request.EntryId.ToString());if(!Row||Request.Version.IsEmpty()||Request.Version!=D::Version(State)||ShopPrice(Row).ToString()!=Request.PriceText){Feedback(TEXT("商品报价已变化，请重新确认"));return;}auto Args=MakeShared<FJsonObject>();Args->SetStringField(TEXT("sku"),Request.EntryId.ToString());Submit(TEXT("Purchase"),Args);}
    else if(Action==TEXT("buy-listing")||Action==TEXT("cancel-listing"))
    {D::FObject Row;if(Action==TEXT("buy-listing"))Row=D::FindCatalog(State,TEXT("market"),Request.EntryId.ToString());else for(const auto& Candidate:D::Rows(D::Object(State,TEXT("market")),TEXT("own_listings")))if(D::String(Candidate,TEXT("id"))==Request.EntryId.ToString()){Row=Candidate;break;}int32 Version=0;if(!Row||Request.Version!=D::Version(Row)||!D::Integer(Row,TEXT("version"),Version)||D::String(Row,TEXT("status"))!=TEXT("Listed"))return;auto Args=MakeShared<FJsonObject>();Args->SetStringField(TEXT("listing_id"),Request.EntryId.ToString());Args->SetNumberField(TEXT("listing_version"),Version);Submit(Action==TEXT("buy-listing")?TEXT("BuyListing"):TEXT("CancelListing"),Args);}
    else if(Action==TEXT("create-listing"))
    {int32 Count=0,Price=0;if(!PositiveInteger(Request.QuantityText,Count)||Count!=Request.Quantity||!PositiveInteger(Request.PriceText,Price))return;const auto Item=D::FindCatalog(State,TEXT("items"),Request.EntryId.ToString());int32 Held=0;if(!Item||!D::Boolean(Item,TEXT("tradeable"))||!D::Integer(Item,TEXT("owned_count"),Held)||Count>Held)return;auto Args=MakeShared<FJsonObject>();Args->SetStringField(TEXT("item_id"),Request.EntryId.ToString());Args->SetNumberField(TEXT("count"),Count);Args->SetNumberField(TEXT("unit_price"),Price);Submit(TEXT("CreateListing"),Args);}
    RefreshAuthority(true);
}
